.sc-tw :root{
  --deep-obsidian: oklch(15% 0.02 280);
  --safety-orange: oklch(65% 0.25 45);
  --titanium-white: oklch(95% 0.01 240);
  --flare-orange: radial-gradient(circle at 50% 50%, oklch(65% 0.25 45 / 0.18), transparent 60%);
}.sc-tw{
  font-family: 'SF Pro Display', sans-serif;
  background-color: var(--deep-obsidian);
  color: var(--titanium-white);
  overflow-x: hidden;
  margin: 0;
  padding: 0;
  view-transition-name: root;
}.sc-tw ::view-transition-old(root),.sc-tw ::view-transition-new(root){
  animation-duration: 0.9s;
  animation-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
}.sc-tw h1,.sc-tw h2,.sc-tw h3,.sc-tw .syncopate{
  font-family: 'Syncopate', sans-serif;
  letter-spacing: -0.02em;
}.sc-tw .kinetic-anchor{
  position: fixed;
  top: 5vh;
  right: -10vw;
  width: 75vw;
  height: 95vh;
  z-index: 0;
  mask-image: 
    polygon(25% 0%, 75% 0%, 100% 50%, 75% 100%, 25% 100%, 0% 50%),
    polygon(30% 10%, 70% 10%, 90% 50%, 70% 90%, 30% 90%, 10% 50%);
  mask-composite: exclude;
  -webkit-mask-image: 
    polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%),
    radial-gradient(circle at 50% 50%, black 30%, transparent 60%);
  -webkit-mask-composite: source-out;
  transform-style: preserve-3d;
  animation: tourbillon-float 24s cubic-bezier(0.25, 0.1, 0.25, 1) infinite alternate;
  pointer-events: none;
  opacity: 0.85;
  filter: drop-shadow(0 0 30px oklch(65% 0.25 45 / 0.3));
}.sc-tw .kinetic-anchor video{
  width: 100%;
  height: 100%;
  object-fit: cover;
  transform: scale(1.3) rotate(-5deg);
  filter: contrast(1.15) brightness(1.05);
}.sc-tw .lens-refraction{
  background: color-mix(in oklch, var(--titanium-white) 2%, transparent);
  backdrop-filter: blur(60px) brightness(1.1);
  -webkit-backdrop-filter: blur(60px) brightness(1.1);
  box-shadow: 
    0 30px 80px -20px rgba(0, 0, 0, 0.9),
    inset 0 1px 1px 0 rgba(255, 255, 255, 0.1),
    inset 0 -1px 1px 0 rgba(255, 255, 255, 0.02),
    inset 0 0 40px oklch(65% 0.25 45 / 0.05);
  border-radius: 24px;
  border: 1px solid rgba(255, 255, 255, 0.03);
  clip-path: polygon(5% 0, 100% 0, 95% 100%, 0 100%);
}.sc-tw .lens-refraction-hex{
  clip-path: polygon(50% 0%, 100% 20%, 100% 80%, 50% 100%, 0% 80%, 0% 20%);
  border-radius: 0;
}.sc-tw .magnetic-liquid{
  background: transparent;
  color: var(--safety-orange);
  position: relative;
  transition: all 0.5s cubic-bezier(0.16, 1, 0.3, 1);
  border: 1px solid var(--safety-orange);
  clip-path: polygon(10% 0, 100% 0, 90% 100%, 0 100%);
  overflow: hidden;
  z-index: 1;
}.sc-tw .magnetic-liquid::before{
  content: '';
  position: absolute;
  top: 100%;
  left: 0;
  width: 100%;
  height: 100%;
  background: var(--safety-orange);
  z-index: -1;
  transition: top 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}.sc-tw .magnetic-liquid:hover{
  color: var(--deep-obsidian);
  transform: translateY(-3px) scale(1.03);
  box-shadow: 0 15px 40px oklch(65% 0.25 45 / 0.4);
}.sc-tw .magnetic-liquid:hover::before{
  top: 0;
}.sc-tw .optical-flare{
  position: absolute;
  width: 180vw;
  height: 180vh;
  background: var(--flare-orange);
  top: -30vh;
  left: -40vw;
  z-index: -1;
  pointer-events: none;
  filter: blur(120px);
  mix-blend-mode: screen;
}

@keyframes tourbillon-float {0%{ transform: translateY(0) rotateZ(0deg) rotateX(2deg) rotateY(-3deg) scale(1); }50%{ transform: translateY(-20px) rotateZ(1deg) rotateX(-1deg) rotateY(1deg) scale(1.02); }100%{ transform: translateY(-40px) rotateZ(-1deg) rotateX(-2deg) rotateY(4deg) scale(1.04); }
}

@keyframes atomic-assembly {from{
    opacity: 0;
    transform: translateY(150px) scale(0.9) rotateX(-15deg) rotateY(10deg);
    filter: blur(20px);
  }to{
    opacity: 1;
    transform: translateY(0) scale(1) rotateX(0deg) rotateY(0deg);
    filter: blur(0);
  }
}.sc-tw .scroll-assembly{
  animation: atomic-assembly linear both;
  animation-timeline: view();
  animation-range: entry 5% cover 40%;
  transform-style: preserve-3d;
}.sc-tw .hex-hub{
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
  gap: 3rem;
  align-items: center;
}.sc-tw .glow-text{
  text-shadow: 0 0 30px oklch(65% 0.25 45 / 0.6);
